const MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];

function partsOf(d) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: tz,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    weekday: 'long',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true
