  const p = Object.fromEntries(parts.map(x => [x.type, x.value]));
  let h = Number(p.hour);
  const ampm = (p.dayPeriod ?? 'AM').toUpperCase();
  if (ampm === 'PM' && h !== 12) h += 12;
  if (ampm === 'AM' && h === 12) h = 0;
  return {
    weekday: p.weekday,
    year: Number(p.year),
    month: Number(p.month),
    day: Number(p.day),
    hour: h,
    minute: Number(p.minute)
  };
}

function fmtTime(d) {
  const p = partsOf(d);
  const h12 = p.hour % 12 === 0 ? 12 : p.hour % 12;
  return h12 + ':' + String(p.minute).padStart(2, '0') + (p.hour < 12 ? ' AM' : ' PM');
}

function fmtDateLong(d) {
  const p = partsOf(d);
  return p.weekday + ', ' + MONTHS[p.month - 1] + ' ' + p.day + ' at ' + fmtTime(d);
}

function fmtDayLabel(d) {
  const p = partsOf(d);
